local config = {
  ui_story_30090401_1_dialog_content = "Aku memandang kotak yang ada di depanku.",
  ui_story_30090401_X1_dialog_content = "Kotak putih berbahan kulit keras yang bersih dan kokoh itu tampak terawat.",
  ui_story_30090401_2_dialog_content = "Gagang logamnya dilapisi kulit halus.",
  ui_story_30090401_3_dialog_content = "Namun, itu hanya sebuah kotak, dan aku sudah memandanginya untuk waktu yang lama.",
  ui_story_30090401_4_dialog_content = "Waktu perlahan berlalu, dan situasi saat ini terasa tidak masuk akal.",
  ui_story_30090401_5_dialog_content = "Ini semua terjadi karena Faust meminta bantuanku.",
  ui_story_30090401_6_dialog_content = "Jadi, kamu mau aku menjaga sebuah <color=#FFB400>koper putih</color>, milikmu.",
  ui_story_30090401_8_dialog_content = "Sebenarnya, Colossus punya tempat khusus untuk menyimpan barang, mungkin kamu bisa menaruhnya di sana.",
  ui_story_30090401_9_dialog_content = "Koper ini berbeda. Kamu harus menjaganya ekstra hati-hati.",
  ui_story_30090401_10_dialog_content = "Saat perlu bantuan, aku biasa menghubungi teman-temanku dari Association—",
  ui_story_30090401_11_dialog_content = "Tapi Lady Victoria sedang sibuk, dan aku tidak tahu di mana Nails dan Pact berada.",
  ui_story_30090401_12_dialog_content = "Aku sadar cuma kamu yang bisa membantuku.",
  ui_story_30090401_13_dialog_content = "Kamu mau ke mana?",
  ui_story_30090401_14_dialog_content = "Untuk membalas budi para pengikutku.",
  ui_story_30090401_15_dialog_content = "Ah—",
  ui_story_30090401_16_dialog_content = "Aku malu mengatakannya, tapi aku punya kelompok penggemar.",
  ui_story_30090401_17_option_content = "Tunggu, tunggu. Aku tidak pernah dengar tentang ini.",
  ui_story_30090401_18_dialog_content = "Soal kelompok penggemarku—",
  ui_story_30090401_19_dialog_content = "Semua penggemarku adalah gadis yang cantik dan perhatian, serta pengikut taat The Truth.",
  ui_story_30090401_20_dialog_content = "Siapa pun akan berterima kasih kalau menerima perhatian sebesar itu, begitu juga aku.",
  ui_story_30090401_21_dialog_content = "*Melihat Faust dengan kaget*",
  ui_story_30090401_22_dialog_content = "Tentu saja, aku juga merasakannya saat PlayerName mengurusku. Aku akan membalasnya pada waktu yang tepat.",
  ui_story_30090401_23_option_content = "Wow, aku juga mau punya kelompok penggemar...",
  ui_story_30090401_24_dialog_content = "Aku sudah sejak awal menjadi pengikut dan penggemarmu.",
  ui_story_30090401_25_dialog_content = "Aku tahu kamu cuma berusaha membuatku senang, tapi caramu berhasil.",
  ui_story_30090401_26_dialog_content = "Aku tidak bohong. Aku tidak pernah bohong.",
  ui_story_30090401_27_dialog_content = "Omong-omong, aku sesekali mengadakan pesta teh untuk para pengikutku. Aku membuat aksesori kecil yang bagus kali ini sebagai tanda terima kasih.",
  ui_story_30090401_28_dialog_content = "Ada versi Bloody Bible, versi Nails, versi Hunting Stone...",
  ui_story_30090401_29_dialog_content = "Dan versi White Suitcase tentu saja—bahkan aku membuat dua versi—hitam dan putih.",
  ui_story_30090401_30_dialog_content = "Tapi...",
  ui_story_30090401_31_dialog_content = "Kotak kecil imutku tidak suka versi mini itu dan memakan semuanya yang aku buat.",
  ui_story_30090401_32_dialog_content = "Tunggu... memakan? Kotak ini bisa makan? Bukannya cuma kotak biasa?",
  ui_story_30090401_33_dialog_content = "Tidak, White Suitcase ini hidup.",
  ui_story_30090401_34_dialog_content = "Maksudmu, White Suitcase ini bernyawa?",
  ui_story_30090401_35_dialog_content = "Ya dan tidak. Dia memang punya temperamen seperti makhluk hidup. Kalau menyimpan banyak hadiah di dalamnya, dia akan marah.",
  ui_story_30090401_36_dialog_content = "Dan dia tidak mudah didekati...",
  ui_story_30090401_37_dialog_content = "Ini juga alasan aku tidak bisa membawanya ke kelompok penggemarku. Aku harus membawa kotak pengganti.",
  ui_story_30090401_38_dialog_content = "Kotak hidup, aneh.",
  ui_story_30090401_39_dialog_content = "Gawat, sudah hampir waktunya!",
  ui_story_30090401_40_dialog_content = "Omong-omong, aku mengandalkanmu, PlayerName!",
  ui_story_30090401_41_dialog_content = "Ini adalah daftar tips mengurus Wispy. Tolong ikuti, ya.",
  ui_story_30090401_42_dialog_content = "Kalau tidak mengikutinya, hal buruk akan terjadi.",
  ui_story_30090401_43_dialog_content = "Hal buruk apa?",
  ui_story_30090401_44_dialog_content = "Misalnya, Colossus dimakan.",
  ui_story_30090401_45_dialog_content = "Apa? Eh, tunggu! Aku tidak paham!!!",
  ui_story_30090401_46_dialog_content = "Jadi, sampai di sinilah kita.",
  ui_story_30090401_47_dialog_content = "Colossus dimakan... Itu pasti lelucon, tidak mungkin.",
  ui_story_30090401_48_dialog_content = "\"... Aku tidak pernah bohong.\"",
  ui_story_30090401_49_dialog_content = "Tapi, aku tidak bisa mengabaikan nasihat orang-orang ini begitu saja...",
  ui_story_30090401_50_dialog_content = "*Melihat daftar*",
  ui_story_30090401_51_dialog_content = "*Membuka sedikit*",
  ui_story_30090401_52_dialog_content = "<color=#FFFFFF>Panduan dan Tips Wispy</color>",
  ui_story_30090401_53_dialog_content = "<size=37><color=#FFFFFF>1. Taruh Wispy di tempat yang tidak terlalu dingin dan tidak terlalu panas.</color></size>",
  ui_story_30090401_A1_dialog_content = "<size=37><color=#FFFFFF>Jaga agar catnya tidak terkelupas atau gagangnya berkarat.</color></size>",
  ui_story_30090401_X53_dialog_content = "<size=37><color=#FFFFFF>2. Bersihkan setiap hari. Gunakan lap untuk membersihkan permukaan koper dengan perlahan.</color></size>",
  ui_story_30090401_A2_dialog_content = "<size=37><color=#FFFFFF>Kalau koper berguncang keras, tunggu sampai dia tenang.</color></size>",
  ui_story_30090401_X54_dialog_content = "<size=37><color=#FFFFFF>3. Jangan membuka paksa koper. Kalau harus membukanya...</color></size>",
  ui_story_30090401_A3_dialog_content = "<size=37><color=#FFFFFF>Pandangi dia dan tunggu dia membuka sendiri.</color></size>",
  ui_story_30090401_X55_dialog_content = "<size=37><color=#FFFFFF>...</color></size>",
  ui_story_30090401_54_dialog_content = "<size=37><color=#FFFFFF>10. Wispy harus diberi makan setiap hari. Waktu makannya adalah tengah hari.</color></size>",
  ui_story_30090401_A4_dialog_content = "<size=37><color=#FFFFFF>Koper harus terbuka agar Wispy bisa diberi makan. Lihat poin No. 3 tentang cara membuka kotak.</color></size>",
  ui_story_30090401_X57_dialog_content = "<size=37><color=#FFFFFF>Kalau lupa memberi makan tepat waktu, sesuatu yang buruk akan terjadi.</color></size>",
  ui_story_30090401_A5_dialog_content = "<size=37><color=#FFFFFF>Sebaiknya kamu tidak tahu apa itu.</color></size>",
  ui_story_30090401_55_dialog_content = "*Menutup*",
  ui_story_30090401_56_dialog_content = "*Mengangkat kepala* Aku terus merasa dia memandangku...",
  ui_story_30090401_57_dialog_content = "Pembersihan harian dan pencegahan penyakit selesai. Aku bisa centang kotak itu.",
  ui_story_30090401_58_dialog_content = "Ini sama sekali bukan tugas mudah. Membersihkannya saja sudah membuatku lelah.",
  ui_story_30090401_59_dialog_content = "Seolah-olah digerakkan mesin, kotak ini berguncang keras setiap kali disentuh.",
  ui_story_30090401_60_dialog_content = "Aku penasaran ada apa di dalamnya?",
  ui_story_30090401_61_dialog_content = "Tinggal satu hal lagi yang belum dilakukan dari daftar ini—memberi makan.",
  ui_story_30090401_62_dialog_content = "Menurut daftar, Wispy makan—",
  ui_story_30090401_63_dialog_content = "Mimpi buruk, kenangan sedih, umpatan saat sekarat, keyakinan yang putus asa, dan air es.",
  ui_story_30090401_64_dialog_content = "Namun, di mana aku bisa menemukan hal-hal aneh ini? Jadi, aku cuma bisa menyiapkan air es.",
  ui_story_30090401_65_dialog_content = "Tapi masih ada kesulitan lagi. Menurut daftar, aku harus memandangnya dan menunggu dia membuka sendiri.",
  ui_story_30090401_66_dialog_content = "Namun, sudah satu jam, dan mataku sudah lelah. Sepertinya kotak ini tidak akan terbuka.",
  ui_story_30090401_67_dialog_content = "...",
  ui_story_30090401_68_dialog_content = "...",
  ui_story_30090401_69_option_content = "Buka paksa",
  ui_story_30090401_70_dialog_content = "Rasanya aku harus memaksanya.",
  ui_story_30090401_71_dialog_content = "*Coba membuka kotak*",
  ui_story_30090401_72_dialog_content = "<color=#e8d9bb>Koper sedikit terbuka.</color>",
  ui_story_30090401_73_dialog_content = "Sepertinya berhasil! Tunggu...",
  ui_story_30090401_74_dialog_content = "Jariku terjepit, sakit!!!!",
  ui_story_30090401_75_dialog_content = "Ini tidak akan berhasil.",
  ui_story_30090401_76_option_content = "Terus memandang",
  ui_story_30090401_77_dialog_content = "*Memandang*",
  ui_story_30090401_78_dialog_content = "*Terus memandang*",
  ui_story_30090401_79_dialog_content = "...",
  ui_story_30090401_X79_dialog_content = "Mataku kering sekali sampai-sampai rasanya mau copot...",
  ui_story_30090401_80_dialog_content = "Aku menyerah.",
  ui_story_30090401_81_dialog_content = "Aku sebaiknya melakukan hal lain saja.",
  ui_story_30090401_82_dialog_content = "*Membuka diam-diam*",
  ui_story_30090401_83_dialog_content = "*Menutup*",
  ui_story_30090401_84_dialog_content = "Apa itu imajinasiku saja? Entahlah, aku akan pergi.",
  ui_story_30090401_85_dialog_content = "*Membuka sedikit lebih lebar*",
  ui_story_30090401_86_dialog_content = "...",
  ui_story_30090401_87_dialog_content = "Hah, kena kamu!!",
  ui_story_30090401_88_dialog_content = "Aku menghabiskan satu jam memandangmu dan kamu tidak mau membuka, tapi begitu aku mau pergi, kamu membuka sendiri. Kamu memang sulit diurus!",
  ui_story_30090401_89_dialog_content = "Cepat minum air es ini, lalu biarkan aku melihat ada apa... di dalammu...",
  ui_story_30090401_90_dialog_content = "Wow! Apa ini?!",
  ui_story_30090401_91_dialog_content = "<color=#e8d9bb>Karena takut, koper menutup sendiri dan berguncang keras beberapa saat sebelum tenang kembali.</color>",
  ui_story_30090401_92_dialog_content = "Untaian-untaian merah, dan kurasa aku melihat sepasang mata yang sangat besar dan terang...",
  ui_story_30090401_93_dialog_content = "Apa Faust menyimpan gurita di dalam sana?",
  ui_story_30090401_94_dialog_content = "Celaka, dia tidak mau membuka lagi, bagaimana aku bisa memberinya makan...",
  ui_story_30090401_95_dialog_content = "Oh, benar! Daftar panduan!",
  ui_story_30090401_96_dialog_content = "\"... Kalau Wispy benar-benar tidak mau membuka, coba tenangkan dengan memujinya.\"",
  ui_story_30090401_97_dialog_content = "Kotak perlu ditenangkan... tidak masuk akal...",
  ui_story_30090401_98_dialog_content = "*Berguncang keras lagi*",
  ui_story_30090401_99_dialog_content = "Maaf, maaf.",
  ui_story_30090401_100_dialog_content = "Ehem, kotak kecil yang imut. Aku membawakanmu air es yang sangat enak dan segar ini!",
  ui_story_30090401_101_dialog_content = "Ayo, terbukalah.",
  ui_story_30090401_102_dialog_content = "*Bergeming*",
  ui_story_30090401_103_dialog_content = "Kotak kecil? Kotak kecil yang imut?",
  ui_story_30090401_104_dialog_content = "Ah, aku harus bagaimana?",
  ui_story_30090401_105_dialog_content = "Aku bahkan tidak bisa mengurus sebuah kotak. Bagaimana aku akan menjawab Faust saat dia kembali?",
  ui_story_30090401_106_dialog_content = "Aku sedih sekali, hiks... hiks...",
  ui_story_30090401_107_dialog_content = "*Membuka perlahan dan menjulurkan untaian*",
  ui_story_30090401_108_dialog_content = "Eh...",
  ui_story_30090401_109_dialog_content = "*Membelai dengan untaian*",
  ui_story_30090401_110_dialog_content = "Kamu menenangkanku? Terima kasih...",
  ui_story_30090401_111_dialog_content = "Mengapa kamu juga menangis? Siapa kira kotak aneh juga punya empati?",
  ui_story_30090401_112_dialog_content = "*Menjabat untaian dengan lembut, seolah-olah setuju*",
  ui_story_30090401_113_dialog_content = "Entah kenapa, tapi aku bisa merasakan kehangatanmu.",
  ui_story_30090401_114_dialog_content = "Terima kasih, Wispy. Kamu jangan ikut sedih.",
  ui_story_30090401_115_dialog_content = "Dia tidak sedih.",
  ui_story_30090401_116_dialog_content = "Oh? Faust, kamu sudah pulang?",
  ui_story_30090401_117_dialog_content = "Ya, acaranya cukup lama.",
  ui_story_30090401_118_dialog_content = "Aku harus memperlakukan para pengikutku yang imut dengan penuh ketulusan.",
  ui_story_30090401_X118_dialog_content = "Walau menggunakan kotak palsu, tidak ada yang tahu.",
  ui_story_30090401_119_dialog_content = "Aku mengeluarkan aksesori dari kotak dan membagikannya. Semua pengikut itu menangis bahagia.",
  ui_story_30090401_120_dialog_content = "Aku bisa melakukannya berkat kamu yang mau mengurus Wispy untukku.",
  ui_story_30090401_121_dialog_content = "Terima kasih, tapi aku masih merasa bersalah sudah membuat Wispy menangis.",
  ui_story_30090401_122_dialog_content = "Bukan, itu bukan air mata.",
  ui_story_30090401_123_dialog_content = "<color=#FFB400>Kenangan sedih adalah makanan favorit Wispy</color>. Dia cuma lapar.",
  ui_story_30090401_124_dialog_content = "Jadi... Dia melihat kesedihan dan keputusasaanku dan air liurnya menetes?",
  ui_story_30090401_125_dialog_content = "Sayangnya, kurasa begitu.",
  ui_story_30090401_126_dialog_content = "*Menggerakkan untaian dengan gembira*",
  ui_story_30090401_127_dialog_content = "Oh, begitu.",
  ui_story_30090401_128_dialog_content = "<size=45>Ehh—</size>",
  ui_story_30090401_129_dialog_content = "<color=#e8d9bb>Wispy itu seperti kucing, punya kepribadian. Perlakukan dia dengan lembut.</color>",
  ui_story_30090601_1_dialog_content = "Pasar Twin Pavilions Bay... Tempat ini terasa seperti selalu ramai, siang dan malam.",
  ui_story_30090601_2_dialog_content = "Hah? Orang di depan itu tampak seperti...",
  ui_story_30090601_3_dialog_content = "Bukan setiap hari kita mendapatkan pemuda tampan yang melihat-lihat barang dagangan kita. Bagaimana kalau begini, aku akan memberimu diskon dua puluh persen untuk buku mana pun yang kamu suka.",
  ui_story_30090601_4_dialog_content = "Terima kasih atas kebaikan hati Anda, Nyonya.",
  ui_story_30090601_5_dialog_content = "Jika buku-buku kuno ini membantu menerangi kebenaran, aku akan selamanya berhutang budi atas kebaikanmu.",
  ui_story_30090601_6_dialog_content = "Kamu sopan sekali, ya! Heheh... Sudah lama tidak ada yang memanggilku \"Nyonya.\"",
  ui_story_30090601_7_dialog_content = "Ngomong-ngomong, saya punya cukup banyak buku tua yang belum lengkap di toko saya. Apakah kamu tertarik untuk melihatnya, pemuda?",
  ui_story_30090601_8_dialog_content = "Tentu saja, saya ingin melihatnya, jika itu tidak masalah bagi Anda.",
  ui_story_30090601_9_dialog_content = "Awalnya, aku tidak begitu yakin dari pakaian itu, tapi sikap dan cara bicaranya...",
  ui_story_30090601_10_dialog_content = "Faust, ini benar-benar kamu.",
  ui_story_30090601_11_dialog_content = "PlayerName? Aku tidak menyangka akan bertemu denganmu di sini. Sungguh kejutan yang menyenangkan.",
  ui_story_30090601_12_dialog_content = "Sedang apa kau di sini? Dan apa urusanmu dengan semua buku itu?",
  ui_story_30090601_13_dialog_content = "Saya baru-baru ini sedang mempelajari budaya kuno Longzhou.",
  ui_story_30090601_14_dialog_content = "Dan saya menemukan bahwa cara terbaik untuk mempelajari suatu budaya adalah dengan benar-benar membenamkan diri di dalamnya.",
  ui_story_30090601_15_dialog_content = "Untuk sepenuhnya memahami pentingnya pakaian, makanan, dan perilaku suatu budaya, seseorang harus mengalaminya secara pribadi.",
  ui_story_30090601_16_dialog_content = "Jadi baru-baru ini, saya tinggal di sini di Twin Pavilions Bay, mengumpulkan sejumlah buku kuno dan peninggalan budaya Longzhou.",
  ui_story_30090601_17_dialog_content = "<color=#e8d9bb>Dor!</color>",
  ui_story_30090601_18_dialog_content = "Ini—ini semua adalah teks lama kita yang acak-acakan.",
  ui_story_30090601_19_dialog_content = "Lagipula, setelah sekian lama, tidak ada yang mau mengambilnya dari tangan saya, jadi jika kamu menginginkannya, ambillah semuanya, gratis.",
  ui_story_30090601_20_dialog_content = "<size=45>Ada begitu banyak dari mereka!</size>",
  ui_story_30090601_21_dialog_content = "Tapi mereka benar-benar sudah hancur berkeping-keping. Tidak ada satu halaman pun dari buku-buku ini yang masih utuh. Apakah kamu masih bisa membacanya...?",
  ui_story_30090601_22_dialog_content = "Aku tidak akan pernah melupakan kemurahan hatimu, Nyonya.",
  ui_story_30090601_23_dialog_content = "Sekarang, tolong izinkan saya untuk meletakkan buku-buku kuno ini di dalam koper saya.",
  ui_story_30090601_24_dialog_content = "Tunggu! Jangan melakukan sesuatu yang begitu berbahaya di depan semua orang ini.",
  ui_story_30090601_25_dialog_content = "Dimana kamu menginap sekarang? Biarkan aku membantu membawanya.",
  ui_story_30090601_26_dialog_content = "Tentu saja. Terima kasih banyak.",
  ui_story_30090601_27_dialog_content = "Wow... Kamu punya buku dan segala macam barang yang berserakan di sini. Kamu benar-benar tidak main-main dalam hal belajar, ya?",
  ui_story_30090601_28_dialog_content = "Nah, Longzhou memiliki sejarah yang sangat panjang, dan merupakan wilayah yang luas dan kaya akan sumber daya.",
  ui_story_30090601_29_dialog_content = "Menjelajahi asal-usul masalah seperti itu bukanlah sesuatu yang bisa diselesaikan dalam semalam.",
  ui_story_30090601_30_dialog_content = "Naskah kuno Longzhou adalah subjek yang membutuhkan studi yang teliti dan mendalam.",
  ui_story_30090601_31_dialog_content = "Formasi karakter melibatkan pictography, ideogram, asosiasi, pictophonetic...",
  ui_story_30090601_32_dialog_content = "Kata-kata yang pernah mengungkapkan suatu makna tertentu mungkin telah berkembang menjadi bentuk yang sepenuhnya berbeda dalam teks tertulis yang ditulis sepuluh atau seratus tahun kemudian.",
  ui_story_30090601_33_dialog_content = "Ambil contoh teks-teks kuno dasar yang baru saja saya baca ini.",
  ui_story_30090601_34_dialog_content = "Karakter ini awalnya memiliki berbagai makna.",
  ui_story_30090601_35_dialog_content = "Tetapi dalam teks-teks selanjutnya, itu dimodifikasi dengan radikal yang berbeda.",
  ui_story_30090601_36_dialog_content = "Dengan menambahkan komponen radikal ini, karakter asli mengembangkan berbagai makna baru...",
  ui_story_30090601_37_dialog_content = "Radikal?",
  ui_story_30090601_38_dialog_content = "Biar aku tulis beberapa untukmu lihat.",
  ui_story_30090601_39_dialog_content = "(Dia bahkan sudah menyiapkan semua kuas kaligrafi dan kertas khusus. Saya rasa dia serius ketika dia mengatakan bahwa dia tengah membenamkan dirinya dalam budaya tersebut.)",
  ui_story_30090601_40_dialog_content = "(Dan... dia sebenarnya cukup pintar melakukannya!)",
  ui_story_30090601_41_dialog_content = "Seperti ini, kamu bisa bercabang ke berbagai makna yang awalnya diwakili oleh satu karakter saja.",
  ui_story_30090601_42_dialog_content = "Meskipun sistem ini sangat rumit, ini juga bisa dengan mudah menimbulkan kebingungan.",
  ui_story_30090601_43_dialog_content = "Apakah karakter ini berarti \"buka\"... atau apakah itu berarti \"mendirikan\"?",
  ui_story_30090601_44_dialog_content = "Hmm? Apakah kamu pernah mempelajari ini sebelumnya?",
  ui_story_30090601_45_dialog_content = "Tidak, hanya saja saya mendengar bahwa kebanyakan hal di Longzhou somehow berhubungan dengan indera.",
  ui_story_30090601_46_dialog_content = "Jadi, karakter ini ditempatkan di dalam radikal yang mewakili pintu, jadi saya rasa maknanya harusnya sesuatu yang mirip dengan membuka pintu... Benar?",
  ui_story_30090601_47_dialog_content = "Dan yang ini berisi bagian kecil yang menunjukkan gerakan... jadi mungkin ini berhubungan dengan ide tentang... \"evasion\"?",
  ui_story_30090601_48_dialog_content = "Itu tepat sekali.",
  ui_story_30090601_49_dialog_content = "Harus kuakui, kamu menunjukkan bakat alami yang luar biasa untuk ini!",
  ui_story_30090601_50_dialog_content = "Ayo, saya tidak tahu banyak tentang karakter-karakter ini.",
  ui_story_30090601_51_dialog_content = "Mungkin saja karena baru-baru ini saya telah berteman dengan banyak orang dari Longzhou dan tanpa sadar mengambil beberapa hal menarik dari mereka.",
  ui_story_30090601_52_dialog_content = "Itu hanya salah satu dari banyak kekuatan supermu.",
  ui_story_30090601_53_dialog_content = "Saya bertanya-tanya, apakah mungkin saya bisa menggunakan koneksi sosial Anda di masa depan untuk melakukan beberapa penelitian lapangan di Longzhou?",
  ui_story_30090601_54_dialog_content = "Mungkin juga ada orang di benua besar itu yang tertarik untuk belajar tentang kekayaan pengetahuan dan banyak kebenaran kita.",
  ui_story_30090601_55_dialog_content = "... Aku tahu itu.",
  ui_story_30090601_56_dialog_content = "Kurasa mereka mungkin bisa melihatnya sebagai berbagi informasi dan mempromosikan komunikasi antara dua benua kita... Itu seharusnya tidak masalah.",
  ui_story_30090601_57_dialog_content = "Maka izinkan saya berterima kasih sebelumnya atas kebaikanmu.",
  ui_story_30090601_58_dialog_content = "Dan sebagai tanda terima kasih...",
  ui_story_30090601_59_dialog_content = "Anda telah mengembangkan beberapa minat pada kaligrafi kuno Longzhou sekarang, bukan?",
  ui_story_30090601_60_dialog_content = "Maukah kamu agar saya mengajari cara menulis karakter ini?",
  ui_story_30090601_61_dialog_content = "<size=45>Hah? Benarkah?</size>Tapi semua karakter ini terlihat sangat rumit...",
  ui_story_30090601_62_dialog_content = "Hanya melalui tindakan, kita bisa mendorong membuka pintu kebenaran.",
  ui_story_30090601_63_dialog_content = "Silakan—ambil tempat duduk.",
  ui_story_30090601_64_dialog_content = "Saya mendukung untuk bertindak, tapi bagaimana saya harus menggunakan sikat ini? Ujungnya sangat lembut, saya hampir tidak bisa mengendalikannya...",
  ui_story_30090601_65_dialog_content = "Ah! Aku telah mengotori semua tempat dengan tinta!",
  ui_story_30090601_66_dialog_content = "Jangan panik.",
  ui_story_30090601_67_dialog_content = "Penulisan seperti ini tidak boleh terburu-buru atau dilakukan sembarangan, dan tidak boleh ada sedikit pun keraguan di hatimu.",
  ui_story_30090601_68_dialog_content = "Kuasmu harus menitikkan tinta di kertas seperti batu yang jatuh dengan tegas dari puncak gunung, meluas secara horizontal, seperti awan yang membentang sejauh ribuan mil, dan meluncur secara vertikal, seperti tanaman merambat yang abadi, memanjat sepanjang masa...",
  ui_story_30090601_69_dialog_content = "Ikuti momentum kuas dan Anda akan menemukan karakter membentuk diri mereka sendiri, secara alami.",
  ui_story_30090601_70_dialog_content = "Titikkan kertas, seperti batu yang jatuh dari puncak gunung.",
  ui_story_30090601_71_dialog_content = "Membentang secara horizontal, seperti awan yang membentang ribuan mil.",
  ui_story_30090601_72_dialog_content = "Meluncur secara vertikal, seperti tanaman merambat yang memanjat untuk selamanya...",
  ui_story_30090601_73_dialog_content = "Saya pikir saya mulai bisa melakukannya! Menghasilkan goresan yang indah ternyata tidak sesulit yang dibayangkan.",
  ui_story_30090601_74_dialog_content = "Tapi... Saya masih berpikir karakter saya belum sepenuhnya setara dengan milik Anda.",
  ui_story_30090601_75_dialog_content = "Sepertinya coretan yang baru saja saya lukis ini bahkan tidak membentuk satu kata pun.",
  ui_story_30090601_76_dialog_content = "Hmm…",
  ui_story_30090601_77_dialog_content = "Apa yang kamu percayai tentang \"kata-kata\", pada dasarnya?",
  ui_story_30090601_78_option_content = "Kurasa aku belum pernah benar-benar memikirkan itu sebelumnya.",
  ui_story_30090601_79_dialog_content = "Memang, semakin sering sesuatu digunakan, semakin besar kemungkinan kita mengabaikan maknanya.",
  ui_story_30090601_80_option_content = "Mereka benar-benar hal yang luar biasa.",
  ui_story_30090601_81_dialog_content = "Jawaban yang bagus.",
  ui_story_30090601_82_dialog_content = "Meskipun kami cukup terbiasa menemukan diri kami terus-menerus dikelilingi oleh kata-kata.",
  ui_story_30090601_83_dialog_content = "Dalam pandangan saya, keberadaan mereka saja adalah keajaiban yang berharga yang harus dikagumi setiap hari.",
  ui_story_30090601_84_dialog_content = "Sebelumnya kamu bertanya-tanya apa tujuan membeli buku-buku tua yang rusak ini.",
  ui_story_30090601_85_dialog_content = "Sekarang, aku akan memberitahumu mengapa aku membelinya.",
  ui_story_30090601_86_dialog_content = "Ini karena kata-kata adalah percikan kebenaran.",
  ui_story_30090601_87_dialog_content = "Melalui kata-kata, pengetahuan dari mereka yang datang sebelum kita dapat dipertahankan dan dikumpulkan.",
  ui_story_30090601_88_dialog_content = "Melampaui gelombang waktu, mereka menjadi puisi yang bisa diceritakan seribu tahun kemudian.",
  ui_story_30090601_89_dialog_content = "Meskipun mereka hanyalah serpihan, sama seperti api yang lahir dari abu—",
  ui_story_30090601_90_dialog_content = "Percikan-percikan yang tersebar ini memiliki kemampuan untuk membangkitkan badai dahsyat dengan hanya sedikit bantuan.",
  ui_story_30090601_91_dialog_content = "Setiap kalimat, setiap kata, setiap karakter dari masa lalu berpotensi menjadi tanda yang ditinggalkan oleh pendahulu kita dalam perjalanan mereka menuju kebenaran.",
  ui_story_30090601_92_dialog_content = "Tentu saja warisan seperti itu layak untuk dihargai dan ditelusuri.",
  ui_story_30090601_93_dialog_content = "Tentu saja!",
  ui_story_30090601_94_dialog_content = "Jadi ketika kamu menulis karakter-karakter ini, jangan terlalu fokus pada sapuan kuasmu.",
  ui_story_30090601_95_dialog_content = "Tanyakan pada diri sendiri mengapa karakter ini memiliki bentuk seperti itu, dan apa makna yang mungkin bisa dimilikinya.",
  ui_story_30090601_96_dialog_content = "Keberanian \"membuka\" dan kerendahan hati \"menghindar\"... Semua itu terletak dalam gerakanmu.",
  ui_story_30090601_97_dialog_content = "Untuk karakter-karakter ini, ini adalah hal yang paling penting.",
  ui_story_30090601_98_dialog_content = "Oke!",
  ui_story_30090601_99_dialog_content = "Kaligrafi sebenarnya banyak mirip dengan kemampuan psikisku. Ini bukan hanya tentang apa yang bisa kamu lihat...",
  ui_story_30090601_100_dialog_content = "Tujuan utama keberadaannya adalah untuk menyampaikan lebih dari yang bisa dilihat hanya dengan mata telanjang.",
  ui_story_30090601_101_dialog_content = "Sekarang kamu juga memahami kebenaran mendalam ini, aku yakin kamu akan bisa menulis dengan lebih percaya diri.",
  ui_story_30090601_102_dialog_content = "Ya! Terima kasih, Faust.",
  ui_story_30090601_103_dialog_content = "Kamu juga harus berusaha untuk memahami pentingnya kata-kata dalam kaitannya dengan kebenaran.",
  ui_story_30090601_104_dialog_content = "Ya!",
  ui_story_30090601_105_dialog_content = "Jadi, itu berarti kamu pasti bersedia untuk bergabung dengan True Order dan mencari kebenaran mutlak sebagai salah satu anggota kami.",
  ui_story_30090601_106_dialog_content = "Ya... aku rasa tidak.",
  ui_story_30090601_107_dialog_content = "Kamu hampir saja mengecohku di sana.",
  ui_story_30090601_108_dialog_content = "Huh... Kupikir mungkin itu akan berhasil kali ini. Sayang sekali.",
  ui_story_30090601_109_dialog_content = "Sudah larut. Mari kita akhiri sesi belajar kita untuk hari ini.",
  ui_story_30090601_110_dialog_content = "Tidak mungkin... Kamu tidak baru saja meminta saya datang hanya untuk mencoba membuat saya bergabung dengan True Order, kan?!",
  ui_story_30090601_111_dialog_content = "Haha... Apakah kamu benar-benar berpikir saya akan melakukan hal seperti itu?",
  ui_story_30090601_112_dialog_content = "... Anda tidak?",
  ui_story_30090601_113_dialog_content = "Terlepas dari niat saya, sangat menyenangkan bertukar pengetahuan tentang sejarah dan budaya denganmu.",
  ui_story_30090601_114_dialog_content = "Dan lihatlah kaligrafi luar biasa yang Anda hasilkan di sini hari ini.",
  ui_story_30090601_115_dialog_content = "Melihat kemajuanmu ke level ini dalam waktu yang singkat memberikan saya kepuasan yang luar biasa sebagai seorang guru.",
  ui_story_30090601_116_dialog_content = "Terima kasih telah membiarkan saya menikmati sore yang begitu memuaskan.",
  ui_story_30090601_117_dialog_content = "Erm... Seharusnya saya yang berterima kasih karena Anda begitu sabar dengan saya. Saya benar-benar belajar banyak hari ini.",
  ui_story_30090601_118_dialog_content = "Nah, jika kamu benar-benar berterima kasih, bolehkah aku membuat permintaan kecil padamu?",
  ui_story_30090601_119_dialog_content = "Aku tidak akan bergabung dengan True Order!",
  ui_story_30090601_120_dialog_content = "Baiklah... Sepertinya aku harus memilih pilihan kedua.",
  ui_story_30090601_121_dialog_content = "Apakah aku benar-benar ingin tahu apa itu \"pilihan kedua\" ini...?",
  ui_story_30090601_122_dialog_content = "Jika saya benar-benar pergi ke Longzhou di masa depan, bisakah Anda menemani saya untuk menghargai karya-karya kaligrafi yang dihasilkan oleh para maestro terkenal dari tanah yang jauh itu?",
  ui_story_30090601_123_dialog_content = "Nah, itu adalah sesuatu yang bisa saya lakukan! Saya sangat menantikannya!",
  ui_story_30090601_124_dialog_content = "Sebelum itu, meskipun... apakah menurutmu saya masih bisa merepotkanmu untuk mengajari saya lebih banyak tentang kaligrafi?",
  ui_story_30090601_125_dialog_content = "Kamu dipersilakan mampir kapan saja kamu suka."
}
